const plain = (t) => String(t || '').replace(/\*\*|__|`|^#+\s*/gm, '').replace(/[\[\]{}]/g, '').replace(/[ \t]+/g, ' ').trim();
const LIST = /^\s*([-*•]|\d+[.)]|\(?[a-dA-D][.)])\s+/;
