  let q = plain(q0);
  let opts = (Array.isArray(opts0) ? opts0 : []).map(plain).filter(Boolean);
  const lines = q.split(/\n+/).map((l) => l.trim()).filter(Boolean);
  const listed = lines.filter((l) => LIST.test(l)).map((l) => l.replace(LIST, '').trim());
